import Foundation

/// Report descriptor of the ILITEK-TOUCH controller (VID 0x222A, PID 0x0001) in an ARZOPA portable monitor.
let ilitekDescriptorHex = ""

func bytes(fromHex hex: String) -> [UInt8] {
    var out: [UInt8] = []
    var i = hex.startIndex
    while i < hex.endIndex {
        let j = hex.index(i, offsetBy: 2)
        out.append(UInt8(hex[i..<j], radix: 16)!)
        i = j
    }
    return out
}
